('00000000-0000-0000-0000-000000000000', 'Kann das SGB meine Krankenversicherung regeln?', 2, '[{"text": "Ja", "correct": true, "because": "SGB V für Gesundheit"}, {"text": "Nein", "correct": false, "because": "Pflichtversicherung geregelt"}]'),
('00000000-0000-0000-0000-000000000000', 'Muss ich als Azubi Beiträge nach dem SGB zahlen?', 2, '[{"text": "Ja", "correct": true, "because": "Sozialversicherungsbeiträge Pflicht"}, {"text": "Nein", "correct": false, "because": "Gesetzlich vorgeschrieben"}]'),
('00000000-0000-0000-0000-000000000000', 'Gilt das SGB nur für Arbeitslose?', 2, '[{"text": "Nein", "correct": true, "because": "Umfasst Versicherungen für alle"}, {"text": "Ja", "correct": false, "because": "SGB III ist nur ein Teil"}]'),
