('00000000-0000-0000-0000-000000000000', 'Sag mir nochmal: Regelt das SGB meine Arbeitszeit?', 2, '[{"text": "Nein", "correct": true, "because": "ArbZG zuständig"}, {"text": "Ja", "correct": false, "because": "Kein direkter Bezug"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann das SGB meinen Urlaub beeinflussen?', 2, '[{"text": "Nein", "correct": true, "because": "BUrlG regelt Urlaub"}, {"text": "Ja", "correct": false, "because": "Kein direkter Einfluss"}]'),
