('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen richtig? a) Das SGB regelt meine Krankenversicherung. b) Es bestimmt meinen Urlaub.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Krankenversicherung ja, Urlaub nein"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Ich zahle Rentenbeiträge nach SGB. b) Es gilt nur für Arbeitslose.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Rente ja, alle betroffen"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Das SGB sichert mich bei Krankheit. b) Es regelt meine Arbeitszeit.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Krankheit ja, Arbeitszeit nein"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Das SGB fordert Beiträge von mir. b) Es gibt mir automatisch Urlaub.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Beiträge ja, Urlaub nein"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]');

